let library, map, canvas, layer, ownMarker, latest, currentCourse=-1, generation=0;
export function demoCoordinates(course,id,minute){const n=Math.min(17.95,Math.max(0,7+(8-id)*.63+minute/14)),i=Math.floor(n),t=n-i;const point=j=>[course.lat+.0055-Math.floor(j/6)*.0045,course.lng-.007+(j%6)*.0027];const a=point(i),b=point(Math.min(17,i+1));return [a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t];}
function leaflet(){if(window.L)return Promise.resolve(window.L);if(!library)library=new Promise((resolve,reject)=>{const css=document.createElement('link');css.rel='stylesheet';css.href='https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';document.head.append(css);const script=document.createElement('script');script.src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';script.onload=()=>resolve(window.L);script.onerror=()=>{library=null;reject(new Error('Map library unavailable'));};document.head.append(script);});return library;}
export async function mountMap(host,course,courseIndex,selected,minute,stale){latest={course,courseIndex,selected,minute,stale};const version=++generation;host.textContent='Loading OpenStreetMap…';try{const L=await leaflet();if(version!==generation||!host.isConnected)return;if(!map){canvas=document.createElement('div');canvas.style.cssText='height:570px;width:100%;background:#dfe6d6';host.replaceChildren(canvas);map=L.map(canvas,{scrollWheelZoom:true}).setView([course.lat,course.lng],15);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).on('tileerror',()=>{const status=document.querySelector('#geo-status');if(status)status.textContent='Some map tiles could not load. Try the illustrated round map.';}).addTo(map);layer=L.layerGroup().addTo(map);}else host.replaceChildren(canvas);if(currentCourse!==courseIndex){currentCourse=courseIndex;map.setView([course.lat,course.lng],15);}map.invalidateSize();layer.clearLayers();for(let id=4;id<=12;id++){const pos=demoCoordinates(course,id,minute);L.circleMarker(pos,{radius:id===selected?12:8,color:'#234b38',weight:2,fillColor:id===8?'#e4c180':'#fffdf0',fillOpacity:stale&&id===8?.4:1}).bindTooltip('DEMO '+String(id).padStart(2,'0'),{permanent:true,direction:'top'}).bindPopup('Simulated group '+id+'. This is an illustrative route, not verified hole geography.').addTo(layer);}}catch{host.textContent='The map could not load. You can still explore the illustrated round map and hole previews.';}}
export function fitCourse(){if(map&&latest)map.setView([latest.course.lat,latest.course.lng],15);}
export function followDemoGroup(){if(map&&latest)map.panTo(demoCoordinates(latest.course,8,latest.minute));}
let watcher=null;
export function stopDeviceLocation(){if(watcher!==null)navigator.geolocation.clearWatch(watcher);watcher=null;if(ownMarker){ownMarker.remove();ownMarker=null;}}
export function showDeviceLocation(onStatus){if(!window.isSecureContext){onStatus('Device location requires HTTPS or localhost.');return;}if(!navigator.geolocation){onStatus('Geolocation is unavailable in this browser.');return;}if(watcher!==null){if(ownMarker&&map)map.panTo(ownMarker.getLatLng());return;}onStatus('Waiting for your location permission…');let first=true;watcher=navigator.geolocation.watchPosition(p=>{if(!map)return;const pos=[p.coords.latitude,p.coords.longitude];if(!ownMarker)ownMarker=L.circleMarker(pos,{radius:10,color:'#fff',weight:3,fillColor:'#347ce1',fillOpacity:1}).bindTooltip('Your device · real GPS',{permanent:true}).addTo(map);else ownMarker.setLatLng(pos);if(first){map.setView(pos,17);first=false;}onStatus('Your device: real GPS, ±'+Math.round(p.coords.accuracy)+'m. Visible only in this browser; no upload. Other groups are simulated.');},e=>{onStatus(e.code===1?'Location permission declined. Map browsing still works.':'Location unavailable: '+e.message);stopDeviceLocation();},{enableHighAccuracy:true,maximumAge:15000,timeout:30000});}
window.addEventListener('pagehide',stopDeviceLocation);
